"use strict";(globalThis.webpackChunkhabitforge_docs=globalThis.webpackChunkhabitforge_docs||[]).push([[788],{6507(o){o.exports=JSON.parse('{"tag":{"label":"moving to habitforge","permalink":"/docs/tags/moving-to-habitforge","allTagsPath":"/docs/tags","count":13,"items":[{"id":"compare/do-habits","title":"Moving from Do Habits to HabitForge","description":"Moving from Do Habits to HabitForge: keep the CSV, turn several-times-a-day goals into one daily check-in, and use pause where you used vacation mode.","permalink":"/docs/compare/do-habits"},{"id":"compare/everyday","title":"Moving from everyday to HabitForge","description":"Moving from everyday to HabitForge: no new-tab board or email reminders here. Write down the habits on your board, re-add them, and expect a missed day to fray, not break.","permalink":"/docs/compare/everyday"},{"id":"compare/fabulous","title":"Moving from Fabulous to HabitForge","description":"Moving from Fabulous to HabitForge: no coach here. Turn the parts of your routine you still do unprompted into habits, and let AI draft the wording only when you ask.","permalink":"/docs/compare/fabulous"},{"id":"compare/habitica","title":"Moving from Habitica to HabitForge","description":"Moving from Habitica to HabitForge: your party, gear and quests stay behind. Which habits to bring, how to sort them into build, break and maintain, and the dated facts.","permalink":"/docs/compare/habitica"},{"id":"compare/habitify","title":"Moving from Habitify to HabitForge","description":"Moving from Habitify to HabitForge: watch, Mac and stacked reminders stay behind. Turn each stacked reminder into a written cue and Off mode into pause.","permalink":"/docs/compare/habitify"},{"id":"compare/habitkit","title":"Moving from HabitKit to HabitForge","description":"Moving from HabitKit to HabitForge: you go from no account and nobody watching to a Google sign-in and a public profile you can switch off. Do that first.","permalink":"/docs/compare/habitkit"},{"id":"compare/habitnow","title":"Moving from HabitNow to HabitForge","description":"Moving from HabitNow to HabitForge: only your habits come; tasks, calendar and timers need another home. Make the backup, leave the one-off tasks, re-add the rest by hand.","permalink":"/docs/compare/habitnow"},{"id":"compare/loop-habit-tracker","title":"Moving from Loop Habit Tracker to HabitForge","description":"Moving from Loop Habit Tracker to HabitForge: you trade a no-account app for a Google sign-in. Keep the CSV, re-add your habits, and see where the rope and Loop\u2019s score agree.","permalink":"/docs/compare/loop-habit-tracker"},{"id":"compare/productive","title":"Moving from Productive to HabitForge","description":"Moving from Productive to HabitForge: templates and place-based reminders stay behind. Write your own habits, or let AI draft one you then save, and keep your paused habits paused.","permalink":"/docs/compare/productive"},{"id":"compare/streaks","title":"Moving from Streaks to HabitForge","description":"Moving from Streaks to HabitForge: on an iPhone you lose the widgets and Apple Health and use the web app. Who should not move, and how to bring 24 tasks across.","permalink":"/docs/compare/streaks"},{"id":"compare/strides","title":"Moving from Strides to HabitForge","description":"Moving from Strides to HabitForge: dated targets stay behind. Bring the daily and weekly habits, mark bad ones as break, and use a challenge where you had an accountability partner.","permalink":"/docs/compare/strides"},{"id":"compare/way-of-life","title":"Moving from Way of Life to HabitForge","description":"Moving from Way of Life to HabitForge: export the CSV or JSON on Android, turn red habits into break habits, and move each diary note into the habit\u2019s cue.","permalink":"/docs/compare/way-of-life"},{"id":"compare/index","title":"Moving to HabitForge","description":"Step-by-step guides for moving to HabitForge from other habit trackers, each with a dated table of prices and features and the sources behind it.","permalink":"/docs/compare"}],"unlisted":false}}')}}]);